(function(){'use strict';
const M=window.NutriDiet,$=id=>document.getElementById(id),storage={getItem:k=>window.localStorage.getItem(k),setItem:(k,v)=>window.localStorage.setItem(k,v)},labels={kcal:['热量','kcal'],protein:['蛋白质','g'],carb:['碳水','g'],fat:['脂肪','g']};
const legacyLabel=document.querySelector('.nutri-demo-label span');if(legacyLabel)legacyLabel.textContent='旧版独立本机记录 · 不与 v3 合成账号互通';
// Original AI illustrations are presentation-only and never enter meal records.
const recipeIllustrations=Object.freeze({
 'CN-PILOT-0001':['tomato-scrambled-eggs-ai-v1.webp','番茄炒蛋'],
 'CN-PILOT-0002':['steamed-egg-custard-ai-v1.webp','蒸蛋羹'],
 'CN-PILOT-0005':['garlic-broccoli-ai-v1.webp','蒜蓉西兰花'],
 'CN-PILOT-0007':['tomato-tofu-soup-ai-v1.webp','番茄豆腐汤'],
 'CN-PILOT-0008':['napa-cabbage-tofu-ai-v1.webp','白菜炖豆腐'],
 'CN-PILOT-0009':['skin-on-steamed-potato-ai-v1.webp','带皮蒸土豆']
});
const conflictGuidance='另一页面更新了此餐记录。当前填写仍保留。请先复制需要保留的内容，返回饮食册并确认放弃当前修改，再点“记一餐”打开最新记录。';
const query=new URLSearchParams(location.search);let slot=M.SLOTS.includes(query.get('slot'))?query.get('slot'):'breakfast',date=M.validDate(query.get('date'))?query.get('date'):localDate(),stage='plan',planIndex=0,dirty=false,photoURL=null,reviewed=null,editToken=null,recordTimeZone=Intl.DateTimeFormat().resolvedOptions().timeZone;
function localDate(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function status(t){$('status').textContent=t;}
function focusPanel(){const target=$(stage==='plan'?'start-record':'editing-header');if(stage!=='plan')target.setAttribute('tabindex','-1');target.focus({preventScroll:true});if(target.scrollIntoView)target.scrollIntoView({block:'start',behavior:'auto'});}
function bookReturnURL(){const q=new URLSearchParams(),allowed=['metabolism','repair','disease','beauty','mental','specific','organ'];if(allowed.includes(query.get('topic'))){q.set('topic',query.get('topic'));if(/^[0-2]$/.test(query.get('group')||''))q.set('group',query.get('group'));if(['0','1'].includes(query.get('open')))q.set('open',query.get('open'));}if(document.body.classList.contains('large-mode'))q.set('large','1');return '../nutrition-booklet.html'+(q.toString()?'?'+q.toString():'');}
function syncLegacyNavigation(){for(const link of document.querySelectorAll('[data-shell-nav] a,.bottom-nav a')){if(!link.href)continue;const page=new URL(link.href,location.href).pathname.split('/').pop();if(!['diet.html','health-calendar.html'].includes(page))continue;link.href=page+'?legacy=1&date='+encodeURIComponent(date)+'&slot='+encodeURIComponent(slot);link.setAttribute('aria-label',page==='diet.html'?'旧版本机饮食记录':'旧版本机日历');}}
document.addEventListener?.('DOMContentLoaded',syncLegacyNavigation,{once:true});
function syncNavigation(){const url=new URL(location.href);url.searchParams.set('date',date);url.searchParams.set('slot',slot);if(stage==='plan')url.searchParams.delete('stage');else url.searchParams.set('stage','record');if(document.body.classList.contains('large-mode'))url.searchParams.set('large','1');else url.searchParams.delete('large');history.replaceState(null,'',url.pathname+url.search+url.hash);document.querySelectorAll('[data-book-return]').forEach(link=>link.href=bookReturnURL());syncLegacyNavigation();}
function nutrientText(t,k){return t[k].value===null?'未知':t[k].value+' '+labels[k][1]+'（'+t[k].known+'/'+t[k].total+' 项）';}
function markDirty(){dirty=true;reviewed=null;$('confirm-actual').checked=false;}
function resetPhoto(){if(photoURL)URL.revokeObjectURL(photoURL);photoURL=null;$('photo-preview').removeAttribute('src');$('photo-preview').hidden=true;$('remove-photo').hidden=true;$('meal-photo').value='';$('meal-album').value='';$('photo-state').textContent='支持 JPG、PNG、WebP，最大 10 MB。';}
function discard(){return !dirty||window.confirm('当前餐次有未保存的修改，放弃这些修改并切换吗？');}
function switchContext(nextDate,nextSlot){if(!discard()){$('diet-date').value=date;return;}date=nextDate;slot=nextSlot;planIndex=0;resetEditor();stage='plan';status('');render();}
function resetEditor(){recordTimeZone=Intl.DateTimeFormat().resolvedOptions().timeZone;editToken=M.token(M.read(storage).meals.find(m=>m.date===date&&m.slot===slot));dirty=false;reviewed=null;$('ingredient-editor').replaceChildren();$('meal-note').value='';$('meal-time').value=({breakfast:'08:00',lunch:'12:00',dinner:'18:00'})[slot];$('confirm-actual').checked=false;$('storage-consent').checked=false;resetPhoto();}
function renderTotals(target,t){
 target.replaceChildren();
 M.FIELDS.forEach(k=>{
  const nutrient=t[k],box=node('div',undefined,'stat');
  const caption=nutrient.value===null?'未知':labels[k][1]+' · '+(nutrient.complete?'已填合计':'部分合计');
  box.append(node('span',labels[k][0]),node('strong',nutrient.value===null?'—':String(nutrient.value)),node('small',caption),node('small','已填 '+nutrient.known+'/'+nutrient.total+' 项'));
  target.append(box);
 });
}
function render(){
 syncNavigation();
 document.body.dataset.stage=stage;$('overview').hidden=stage!=='plan';$('editing-header').hidden=stage==='plan';$('editing-title').textContent='记录'+M.LABELS[slot];$('editing-date').textContent=date+' · 仅本机保存';$('record-step').classList.toggle('current',stage==='record');$('review-step').classList.toggle('current',stage==='review');
 $('diet-date').value=date;document.querySelectorAll('[data-slot]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.slot===slot)));document.querySelectorAll('.step-tabs [data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.stage===stage)));['plan','record','review'].forEach(s=>$(s+'-panel').hidden=s!==stage);
 const url='health-calendar.html?legacy=1&date='+encodeURIComponent(date)+'&slot='+encodeURIComponent(slot)+'&type=diet';$('calendar-link').href=url;$('view-calendar').href=url;
 const r=M.read(storage);if(!r.ok)status(r.message);const summary=M.summary(r.meals,date);renderTotals($('daily-totals'),summary.nutrients);$('coverage').textContent='已记 '+summary.mealCount+'/3 餐'+(summary.missingSlots.length?'；未记：'+summary.missingSlots.map(s=>M.LABELS[s]).join('、'):'')+'。部分合计表示仍有食物未填该项数值；未填写不按零计。数值来自你的标签录入或手工估算，不含未记录食物。';
 renderBookIntake(summary);document.querySelectorAll('[data-slot]').forEach(b=>{const saved=r.meals.find(m=>m.date===date&&m.slot===b.dataset.slot);const sub=b.querySelector('small');if(sub)sub.textContent=saved?'已记录 · '+saved.time:'未记录';});renderPlan();renderSaved(r.meals);
}
function renderBookIntake(summary){
 $('meal-count').textContent=summary.mealCount?'已记 '+summary.mealCount+'/3 餐 · 仅已填数值':'还没记录，从这一餐开始';
 const rows=document.querySelectorAll('.macro');['carb','fat','protein'].forEach((k,i)=>{const n=summary.nutrients[k];rows[i].querySelector('span').textContent=n.value===null?'未知':n.value+' 克'+(n.complete?'':' · 部分合计');rows[i].querySelector('.track').setAttribute('aria-hidden','true');});
 $('intake-title').textContent=date===localDate()?'今天吃得怎么样？':'这天吃得怎么样？';
}
function renderPlan(){const plans=M.plans(window.RECIPES,slot),p=plans[planIndex%Math.max(1,plans.length)],host=$('plan-content');host.replaceChildren();$('plan-heading').textContent=M.LABELS[slot]+'搭配建议';$('use-plan').disabled=!p;$('swap-plan').disabled=plans.length<2;if(!p){host.append(node('p','食谱未加载，请直接手动记录。'));return;}
 const heading=node('div',undefined,'recipe-summary'),copy=node('div',undefined,'recipe-summary-copy');copy.append(node('h3',p.title,'recipe-title'));heading.append(copy);
 const artwork=Object.prototype.hasOwnProperty.call(recipeIllustrations,p.recipeId)?recipeIllustrations[p.recipeId]:null;
 if(artwork){
  heading.classList.add('recipe-summary-illustrated');
  const figure=node('figure',undefined,'recipe-illustration'),img=node('img'),caption=node('figcaption','AI 生成示意图'),note=node('p','图示仅为'+artwork[1]+'，不代表实际份量。','recipe-image-note');
  figure.dataset.recipeId=p.recipeId;img.src='../assets/recipes/'+artwork[0];img.alt=artwork[1]+'的 AI 手绘示意图，非实拍，不代表搭配或摄入份量';img.width=720;img.height=480;img.loading='lazy';img.decoding='async';
  img.addEventListener('error',()=>{figure.remove();note.remove();heading.classList.remove('recipe-summary-illustrated');});
  figure.append(img,caption);heading.append(figure);copy.append(note);
 }
 host.append(heading,node('p',p.ingredients.map(i=>i.name+' '+i.grams+'g').join(' · '),'recipe-ingredients'));
 const d=node('details',undefined,'recipe-detail'),sum=node('summary','做法、食材提醒与来源');d.append(sum);const ol=node('ol');p.steps.forEach(step=>ol.append(node('li',step)));d.append(ol,node('p','按食材与包装核对过敏原。含蛋、奶、大豆等时尤其留意；此提示不是完整过敏原筛查。','hint'),node('p',p.source,'source'),node('p','这是配方示例，不代表已经吃下。原配方营养数字尚未核验，不直接用于摄入合计；记录时可填包装标签或有依据的估算。','hint'));host.append(d);
}
function beginRecord(){
 if(!dirty){const existing=M.read(storage).meals.find(m=>m.date===date&&m.slot===slot);resetEditor();if(existing){editToken=M.token(existing);recordTimeZone=existing.timeZone;existing.items.forEach(addItem);$('meal-time').value=existing.time;$('meal-note').value=existing.note;status('已打开这餐记录，可补充食物后重新确认保存。');}else status('');}
 goStage('record');
}
function makeInput(label,field,value,type){const l=node('label',label),i=node('input');i.type=type||'text';i.dataset.field=field;i.value=value===null||value===undefined?'':value;if(i.type==='number'){i.min='0';i.step='any';i.inputMode='decimal';}l.append(i);return l;}
function addItem(item){if($('ingredient-editor').children.length>=40){status('一餐最多记录 40 项食物。');return;}item=item||{};const card=node('div',undefined,'ingredient-card'),row=node('div',undefined,'field-row');row.append(makeInput('食物名称','name',item.name),makeInput('实际吃下（g）','grams',item.grams,'number'));row.querySelector('[data-field=name]').maxLength=100;row.querySelector('[data-field=grams]').max='10000';card.append(row);const details=node('details'),summary=node('summary','营养值（选填） · 每 100 g');details.append(summary,node('p','仅填写和此食物状态一致的数值。能量单位是 kcal（千卡）；包装若标 kJ，须先除以 4.184。留空代表未知。','hint'));const fields=node('div',undefined,'nutrient-fields');M.FIELDS.forEach(k=>fields.append(makeInput(labels[k][0]+'（'+labels[k][1]+'）',k,item.nutrientsPer100g&&item.nutrientsPer100g[k],'number')));details.append(fields);const sourceLabel=node('label','数值来源','source-label'),select=node('select');select.dataset.field='source';[['unknown','尚未填写'],['user-label','我录入的包装标签'],['user-estimate','我手工估算（非测量）']].forEach(([v,t])=>{const o=node('option',t);o.value=v;select.append(o);});select.value=item.source||'unknown';sourceLabel.append(select);const note=makeInput('标签产品名称 / 估算依据','sourceNote',item.sourceNote);note.className='source-label';note.querySelector('input').maxLength=160;details.append(sourceLabel,note);card.append(details);const remove=node('button','移除此项','remove-item');remove.type='button';remove.addEventListener('click',()=>{card.remove();markDirty();});card.append(remove);card.addEventListener('input',markDirty);card.addEventListener('change',markDirty);$('ingredient-editor').append(card);}
function collect(){const items=Array.from($('ingredient-editor').children).map(c=>{const v=k=>c.querySelector('[data-field="'+k+'"]').value;return {name:v('name'),grams:v('grams'),unit:'g',nutrientsPer100g:Object.fromEntries(M.FIELDS.map(k=>[k,v(k)])),source:v('source'),sourceNote:v('sourceNote')};});return M.normalizeMeal({date,slot,time:$('meal-time').value,items,note:$('meal-note').value,confirmed:true,timeZone:recordTimeZone});}
function goStage(s){if(s==='review'){try{reviewed=collect();}catch(e){status(e.message);return;}renderReview();}if(s==='record'&&!$('ingredient-editor').children.length)addItem();stage=s;render();focusPanel();}
function renderReview(){const host=$('review-content');host.replaceChildren();host.append(node('h3',date+' · '+M.LABELS[slot]+' · '+reviewed.time));const ul=node('ul',undefined,'ingredient-list');reviewed.items.forEach(i=>ul.append(node('li',i.name+' '+i.grams+' g'+(i.source==='unknown'?' · 营养值未知':' · '+(i.source==='user-label'?'包装标签：':'手工估算：')+i.sourceNote))));host.append(ul);const t=M.totals(reviewed.items);M.FIELDS.forEach(k=>host.append(node('p',labels[k][0]+'：'+nutrientText(t,k))));const existing=M.read(storage).meals.some(m=>m.date===date&&m.slot===slot);$('replace-note').textContent=existing?'此日期、此餐次已有记录。保存会替换该餐原文字记录，请确认内容完整。':'保存后会显示在本机健康日历中。';$('confirm-actual').checked=false;}
function renderSaved(meals){const host=$('saved-meals');host.replaceChildren();const selected=meals.filter(m=>m.date===date).sort((a,b)=>M.SLOTS.indexOf(a.slot)-M.SLOTS.indexOf(b.slot));if(!selected.length)host.append(node('p','还没有实际饮食记录。选择建议不会自动算作摄入。'));selected.forEach(m=>{const box=node('div',undefined,'saved-row'),t=M.totals(m.items);box.append(node('h3',M.LABELS[m.slot]+' · '+m.time),node('p',m.items.map(i=>i.name+' '+i.grams+'g').join('、')),node('p','热量：'+nutrientText(t,'kcal')+'；仅包含已填数值。','hint'));const edit=node('button','查看 / 修改'),del=node('button','删除此餐');edit.type=del.type='button';edit.addEventListener('click',()=>{if(!discard())return;slot=m.slot;resetEditor();editToken=M.token(m);recordTimeZone=m.timeZone;m.items.forEach(addItem);$('meal-time').value=m.time;$('meal-note').value=m.note;dirty=false;stage='record';status('修改后需再次确认并保存，才会更新日历。');render();focusPanel();});del.addEventListener('click',()=>{if(!window.confirm('删除 '+date+' '+M.LABELS[m.slot]+' 的本机文字记录？此操作无法撤销。'))return;const r=M.remove(storage,m.id,M.token(m));status(r.ok?'已删除这餐本机记录。':r.message);render();});box.append(edit,del);host.append(box);});}
$('diet-date').addEventListener('change',e=>{if(!M.validDate(e.target.value)){status('请选择有效日期。');e.target.value=date;return;}switchContext(e.target.value,slot);});$('today').addEventListener('click',()=>switchContext(localDate(),slot));document.querySelectorAll('[data-slot]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.slot!==slot)switchContext(date,b.dataset.slot);}));document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>goStage(b.dataset.stage)));
$('swap-plan').addEventListener('click',()=>{planIndex++;renderPlan();});$('use-plan').addEventListener('click',()=>{if(dirty&&!window.confirm('用此建议替换尚未保存的餐食填写内容？'))return;const p=M.plans(window.RECIPES,slot)[planIndex%M.plans(window.RECIPES,slot).length];resetEditor();p.ingredients.forEach(addItem);markDirty();goStage('record');status('建议已填入。请把份量改成实际吃下的数量，未吃的项目请移除。');});$('manual-start').addEventListener('click',beginRecord);$('start-record').addEventListener('click',beginRecord);$('tool-record').addEventListener('click',beginRecord);$('cancel-edit').addEventListener('click',()=>{if(!discard())return;resetEditor();stage='plan';status('');render();focusPanel();});$('show-intake').addEventListener('click',()=>{const open=$('intake-detail').hidden;$('intake-detail').hidden=!open;$('show-intake').setAttribute('aria-expanded',String(open));$('show-intake').textContent=open?'收起明细 ⌃':'查看摄入 ›';document.querySelector('.macros').hidden=open;if(open){$('intake-detail').setAttribute('tabindex','-1');$('intake-detail').focus({preventScroll:true});}});$('large').addEventListener('click',()=>{const on=document.body.classList.toggle('large-mode');$('large').setAttribute('aria-pressed',String(on));$('large').textContent=on?'标准':'大字';syncNavigation();});$('add-item').addEventListener('click',()=>{addItem();markDirty();});$('review-meal').addEventListener('click',()=>goStage('review'));$('meal-time').addEventListener('input',markDirty);$('meal-note').addEventListener('input',markDirty);
['meal-photo','meal-album'].forEach(inputId=>$(inputId).addEventListener('change',()=>{const f=$(inputId).files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10*1024*1024){resetPhoto();status('请选择不超过 10 MB 的 JPG、PNG 或 WebP 图片。');return;}if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(f);$('photo-preview').src=photoURL;$('photo-preview').hidden=false;$('remove-photo').hidden=false;$('photo-state').textContent='仅本页预览。未做图像识别；请在下方手动确认食材。';}));$('photo-preview').addEventListener('error',()=>{resetPhoto();status('图片无法解码，请换一张 JPG、PNG 或 WebP 图片。');});$('remove-photo').addEventListener('click',resetPhoto);
$('save-meal').addEventListener('click',()=>{if(!reviewed||!$('confirm-actual').checked){status('请先核对并勾选实际食材与份量确认。');return;}const result=M.save(storage,reviewed,$('storage-consent').checked,editToken);if(result.conflict){reviewed=null;$('confirm-actual').checked=false;}status(result.ok?'已保存实际文字记录，健康日历已可查看。照片没有保存。':result.conflict?conflictGuidance:result.message);if(result.ok){editToken=M.token(result.meal);dirty=false;reviewed=null;resetPhoto();$('confirm-actual').checked=false;stage='plan';render();focusPanel();}});
window.addEventListener('storage',e=>{if(e.key===M.KEY||e.key===null){const current=M.read(storage);const latest=M.token(current.meals.find(m=>m.date===date&&m.slot===slot));if(dirty&&(!current.ok||latest!==editToken)){reviewed=null;$('confirm-actual').checked=false;status(conflictGuidance);}render();}});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});window.addEventListener('pagehide',()=>{if(photoURL)URL.revokeObjectURL(photoURL);});resetEditor();render();if(query.get('large')==='1')$('large').click();if(query.get('stage')==='record')beginRecord();if(query.get('stage')==='intake')$('show-intake').click();
})();
